import hashlib,os
R='/home/na/projects/evo-sim/sources/raw/sources/'
def sha(p):
    h=hashlib.sha256()
    with open(R+p,'rb') as f:
        for c in iter(lambda:f.read(1<<20),b''): h.update(c)
    return h.hexdigest()
