out=['# Bibliography: primary scientific literature (R1 pass 2)','',
'Generated 2026-10-07 by the literature-harvest agent. `local path` is under `sources/raw/sources/` (gitignored; never committed). `sha256` is of the raw downloaded file (the first listed file when several). Access vocabulary: **OA full** = full text retrieved; **OA exists, not retrieved** = free copy exists but automated download is blocked by a bot challenge (not bypassed); **paywalled** = abstract only; **record only** = not obtainable. "cited-by" is taken from PLAN.md pass-1 and not re-verified unless stated.','',
'| key | full citation | DOI | OA URL | local path | sha256 | access | cited-by | branch | notes |','|---|---|---|---|---|---|---|---|---|---|']
for k,c,d,u,paths,acc,cb,br,n in E:
    lp='<br>'.join('`'+p+'`' for p in paths) or '-'
    sh='<br>'.join(sha(p)[:64] if os.path.getsize(R+p)>0 else '-' for p in paths[:1]) if paths else '-'
    if len(paths)>1:
        sh+='<br>(+ '+', '.join(p.split('/')[-1]+':'+sha(p)[:12] for p in paths[1:] if p.endswith(('.pdf','.xlsx','.xml')))+')'
    out.append(f'| {k} | {c} | {d or "-"} | {u} | {lp} | {sh} | {acc} | {cb} | {br} | {n} |')
open('/home/na/projects/evo-sim/docs/research/sources/bib-literature.md','w').write('\n'.join(out)+'\n')
